insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_70_v1'
from (values
('127.475.d.1.A',3,'A student watches bacteria stop growing near a spot of mold on a dish and asks why. This step is called asking a:','["question based on an observation", "product label", "final grade", "safety poster"]'::jsonb,0,'Science starts with questions from observations.','original'),
('127.475.d.1.A',4,'Before an experiment, a scientist writes down exactly what is unknown and what will be measured. This is called:','["ordering supplies", "defining the problem", "cleaning the bench", "grading the data"]'::jsonb,1,'A clear problem statement guides the design.','original'),
('127.475.d.1.B',3,'An experiment that changes only one factor at a time and keeps all others the same is a:','["random guess", "survey of opinions", "controlled investigation", "model drawing"]'::jsonb,2,'Controls isolate one variable.','original'),
('127.475.d.1.B',4,'Comparing the growth of bacteria at 25 and 37 degrees Celsius is a comparative investigation because it:','["uses no data", "needs no measuring", "has no variables", "tests two conditions against each other"]'::jsonb,3,'Comparison needs two or more conditions.','original'),
('127.475.d.1.C',3,'Before handling chemicals in a biotechnology lab, a student should put on:','["goggles, gloves, and a lab coat", "headphones", "a scarf and sunglasses", "sandals and a hat"]'::jsonb,0,'Standard PPE protects eyes, skin, and clothes.','original'),
('127.475.d.1.C',4,'If a culture tube breaks on the floor, the safest first step is to:','["leave the room quietly", "alert the teacher and follow spill procedures", "sweep it up bare-handed", "ignore it"]'::jsonb,1,'Spills are reported and cleaned with proper steps.','original'),
('127.475.d.1.D',3,'To see single bacterial cells, a student would use a:','["thermometer", "meter stick", "microscope", "balance"]'::jsonb,2,'Bacteria are too small to see without magnification.','original'),
('127.475.d.1.D',4,'A thermocycler is a tool that repeatedly heats and cools samples, which is needed to copy DNA by:','["filtering", "weighing", "staining", "PCR"]'::jsonb,3,'PCR cycles through temperatures.','original'),
('127.475.d.1.E',3,'In the International System of Units, volume of liquids in a lab is commonly measured in:','["milliliters", "ounces", "pints", "inches"]'::jsonb,0,'SI volume units include liter and milliliter.','original'),
('127.475.d.1.E',4,'A scientist records a mass of 0.25 grams. Written in milligrams, this is:','["2,500 mg", "250 mg", "25 mg", "2.5 mg"]'::jsonb,1,'0.25 g x 1,000 = 250 mg.','original'),
('127.475.d.1.F',3,'Scientists write data in a laboratory notebook so that others can:','["avoid reading it", "skip the procedure", "repeat and check the work", "guess the results"]'::jsonb,2,'Records support reproducibility.','original'),
('127.475.d.1.F',4,'A good lab notebook entry is dated, written in ink, and includes data tables, observations, and:','["unrelated news", "doodles only", "a grocery list", "the procedure that was followed"]'::jsonb,3,'Complete records show what was done.','original'),
('127.475.d.1.G',3,'A diagram showing how a plasmid is cut and joined to a gene is an example of a:','["model", "patent fee", "product label", "raw material"]'::jsonb,0,'Models represent processes.','original'),
('127.475.d.1.G',4,'A model of DNA made from colored beads helps students understand a structure that is:','["not real", "too small to see directly", "too large to hold", "unchanging in every way"]'::jsonb,1,'Models represent hidden or tiny systems.','original'),
('127.475.d.1.H',3,'A well-tested explanation of why traits are inherited, supported by many experiments, is a scientific:','["wish", "rumor", "theory", "guess"]'::jsonb,2,'A theory is a well-supported explanation.','original'),
('127.475.d.1.H',4,'A statement that describes what always happens in nature, such as conservation of mass, is a scientific:','["proposal", "opinion", "hypothesis", "law"]'::jsonb,3,'Laws describe patterns; theories explain them.','original'),
('127.475.d.2.A',3,'A limitation of a small plastic model of a cell is that it:','["cannot show every real function", "is the actual cell", "is always correct", "never helps"]'::jsonb,0,'Models simplify reality.','original'),
('127.475.d.2.A',4,'A model drawn much larger than real life has an advantage of showing detail but the limitation that it changes the:','["name", "scale", "meaning of life", "subject"]'::jsonb,1,'Scale is a common model limitation.','original'),
('127.475.d.2.B',3,'A scientist who notices that growth rises as temperature rises and then falls has found a:','["missing label", "safety rule", "pattern in the data", "broken tool"]'::jsonb,2,'Patterns appear in data.','original'),
('127.475.d.2.B',4,'An average of repeated trials helps a scientist reduce the effect of one unusual:','["reagent", "variable name", "notebook", "outlier"]'::jsonb,3,'Averaging reduces the influence of outliers.','original'),
('127.475.d.2.C',3,'A solution is made by adding 5 grams of salt to 100 mL of water. The concentration in grams per mL is:','["0.05", "5", "0.5", "20"]'::jsonb,0,'5 / 100 = 0.05.','original'),
('127.475.d.2.C',4,'If a sample contains 12 colonies per plate and there are 4 plates, the total number of colonies is:','["3", "48", "16", "8"]'::jsonb,1,'12 x 4 = 48.','original'),
('127.475.d.2.D',3,'Judging whether a design works well, is safe, and meets its goals is called:','["hiding it", "naming it", "evaluating the design", "decorating it"]'::jsonb,2,'Evaluation compares results with goals.','original'),
('127.475.d.2.D',4,'An engineer finds that a bioreactor design gives low yield. The next best step is to:','["blame the tools", "stop all work", "ignore the data", "redesign using the data"]'::jsonb,3,'Data guides improvements.','original'),
('127.475.d.3.A',3,'A scientist proposes that a nutrient boosts bacterial growth and backs it up with graphs. This is an explanation supported by:','["data", "opinion polls", "luck", "rumors"]'::jsonb,0,'Claims need evidence.','original'),
('127.475.d.3.A',4,'A proposed solution to contaminated cultures is stronger if it is supported by data and a:','["loud voice", "model of how contamination spreads", "new logo", "longer title"]'::jsonb,1,'Models and data support solutions.','original'),
('127.475.d.3.B',3,'Scientists share results with a team by writing reports, giving talks, and using:','["silence", "secret codes", "charts and graphs", "guesses"]'::jsonb,2,'Visuals communicate results.','original'),
('127.475.d.3.B',4,'When working in a lab group, each member should share findings and listen to others so the team can reach a:','["longer break", "fixed answer", "quicker argument", "stronger conclusion"]'::jsonb,3,'Collaboration improves conclusions.','original'),
('127.475.d.3.C',3,'In scientific argumentation, a respectful scientist responds to a disagreement by:','["asking for evidence", "mocking", "walking out", "shouting"]'::jsonb,0,'Arguments rest on evidence.','original'),
('127.475.d.3.C',4,'A student disagrees with a classmate''s conclusion. The most scientific response is to:','["refuse to talk", "explain the data that support another view", "change the data", "say the classmate is wrong because of age"]'::jsonb,1,'Evidence-based reasoning is respectful.','original'),
('127.475.d.4.A',3,'Critiquing a scientific explanation means checking whether its claims are supported by:','["the author''s age", "popularity", "evidence", "a catchy title"]'::jsonb,2,'Critique checks the evidence.','original'),
('127.475.d.4.A',4,'A news story claims a supplement cures all disease based on one story from one person. A critic would point out that this is:','["a controlled trial", "a proven law", "peer reviewed data", "insufficient evidence"]'::jsonb,3,'One anecdote is not strong evidence.','original'),
('127.475.d.4.B',3,'The discovery of the structure of DNA changed scientific thought by showing how genetic information could be:','["copied and passed on", "erased", "ignored", "hidden"]'::jsonb,0,'Structure explained replication.','original'),
('127.475.d.4.B',4,'Early research on antibiotics from mold changed medicine because it led to treatments for:','["tooth color", "bacterial infections", "broken bones", "eyesight only"]'::jsonb,1,'Antibiotics treat bacterial disease.','original'),
('127.475.d.4.C',3,'A student looking for reliable information about a biotechnology career could visit a:','["random social post", "advertisement only", "professional organization or university", "gossip site"]'::jsonb,2,'Reliable sources include experts and institutions.','original'),
('127.475.d.4.C',4,'Museums, libraries, and professional organizations are good resources because they provide:','["only entertainment", "unchecked rumors", "free lunch", "reliable, reviewed information"]'::jsonb,3,'Credible sources support research.','original'),
('127.475.d.5.A',3,'Using living cells or organisms to make useful products is called:','["biotechnology", "astronomy", "geography", "carpentry"]'::jsonb,0,'Biotech uses biology for products.','original'),
('127.475.d.5.A',4,'Insulin made by bacteria that carry a human gene is an example of a:','["weather event", "biotechnology product", "mineral", "fossil"]'::jsonb,1,'Recombinant insulin is a biotech product.','original'),
('127.475.d.5.B',3,'Comparing a person''s DNA sequence with a database to look for matches uses:','["navigation", "pottery", "bioinformatics", "bookkeeping"]'::jsonb,2,'Bioinformatics uses computers for biological data.','original'),
('127.475.d.5.B',4,'Matching DNA from a crime scene to a database and mapping a genome both rely on software that stores and analyzes:','["sports scores", "tax forms", "music files", "sequence data"]'::jsonb,3,'Bioinformatics handles sequences.','original'),
('127.475.d.5.C',3,'A scientist who studies genes and uses computers to analyze them might work in the career field of:','["bioinformatics", "plumbing", "aviation", "landscaping"]'::jsonb,0,'Bioinformatics is a career field.','original'),
('127.475.d.5.C',4,'Careers in genetics often require college study in biology plus skills in:','["painting only", "laboratory work and data analysis", "driving trucks only", "retail sales only"]'::jsonb,1,'Genetics careers need lab and data skills.','original'),
('127.475.d.5.D',3,'Rosalind Franklin''s X-ray images contributed to biotechnology by helping reveal the structure of:','["a cloud", "an engine", "DNA", "a volcano"]'::jsonb,2,'Her images aided the double helix model.','original'),
('127.475.d.5.D',4,'Scientists from many backgrounds have contributed to biotechnology, which shows that discovery depends on:','["one tool only", "luck alone", "one country only", "diverse people and ideas"]'::jsonb,3,'Diverse contributions advance science.','original'),
('127.475.d.5.E',3,'The study of right and wrong in biology and medicine, such as whether to edit human genes, is called:','["bioethics", "grammar", "economics", "geometry"]'::jsonb,0,'Bioethics weighs moral questions.','original'),
('127.475.d.5.E',4,'A bioethics committee reviews an experiment on human volunteers to make sure the people are:','["paid in secret", "protected and informed", "unaware", "excluded"]'::jsonb,1,'Ethics protects participants.','original'),
('127.475.d.5.F',3,'When people disagree about genetically modified foods, a good thinker should:','["pick the loudest side", "insult opponents", "weigh evidence from several points of view", "ignore all facts"]'::jsonb,2,'Evaluate multiple viewpoints.','original'),
('127.475.d.5.F',4,'To evaluate a claim about gene editing in the news, a student should check the source, the evidence, and any:','["picture size", "headline length", "font", "bias"]'::jsonb,3,'Bias affects reliability.','original'),
('127.475.d.5.G',3,'A crop given a gene to resist insects is an example of agricultural biotechnology called a:','["genetically modified organism", "mineral deposit", "weather satellite", "fossil fuel"]'::jsonb,0,'GMOs carry added genes.','original'),
('127.475.d.5.G',4,'Golden Rice was developed to help prevent a vitamin deficiency by making the grain produce:','["antibiotics", "beta-carotene", "cholesterol", "caffeine"]'::jsonb,1,'Beta-carotene becomes vitamin A.','original'),
('127.475.d.5.H',3,'A vaccine produced using biotechnology trains the body''s immune system to recognize a:','["metal", "rock", "pathogen", "fabric"]'::jsonb,2,'Vaccines prepare immunity.','original'),
('127.475.d.5.H',4,'Growing human insulin in bacteria is an application of medical biotechnology that helps people with:','["freckles", "hiccups", "sunburn", "diabetes"]'::jsonb,3,'Insulin treats diabetes.','original'),
('127.475.d.5.I',3,'Forensic scientists use capillary electrophoresis to separate pieces of DNA by:','["size", "smell", "color", "taste"]'::jsonb,0,'Fragments are separated by length.','original'),
('127.475.d.5.I',4,'A DNA profile from a crime scene can help forensic scientists:','["price a house", "identify a person", "fix a car", "predict weather"]'::jsonb,1,'DNA profiling identifies individuals.','original'),
('127.475.d.5.J',3,'Using microbes to clean up an oil spill is an example of:','["welding", "recycling paper", "bioremediation", "mining"]'::jsonb,2,'Bioremediation uses organisms to break down pollution.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_70_v1'
from (values
('127.475.d.5.J',4,'Besides bioremediation, waste can also be reduced by non-biotechnology solutions such as:','["building bigger landfills only", "burning plastics in homes", "more littering", "recycling and composting"]'::jsonb,3,'Several approaches reduce waste.','original'),
('127.475.d.6.A',3,'The biotechnology industry has sectors such as medical, agricultural, and:','["industrial", "athletic", "musical", "culinary arts only"]'::jsonb,0,'Industrial biotech is a major sector.','original'),
('127.475.d.6.A',4,'A company that makes enzymes for laundry detergent works in which biotechnology sector?','["veterinary only", "industrial", "forensic", "medical"]'::jsonb,1,'Enzyme manufacturing is industrial biotech.','original'),
('127.475.d.6.B',3,'A lab in the medical sector might use PCR to detect a virus in a patient sample, while an agricultural lab may use it to detect:','["a rock layer", "a song", "a gene in a crop", "a cloud type"]'::jsonb,2,'PCR is used across sectors.','original'),
('127.475.d.6.B',4,'Gel electrophoresis is used in forensic labs to compare DNA samples, and in medical labs to check for:','["road conditions", "paint colors", "fabric types", "genetic differences"]'::jsonb,3,'Techniques are shared across sectors.','original'),
('127.475.d.6.C',3,'A medical biotech lab makes vaccines, while an agricultural biotech lab develops pest-resistant crops. They differ in their:','["applications", "laws of physics", "number of days", "gravity"]'::jsonb,0,'Sectors apply the same science differently.','original'),
('127.475.d.6.C',4,'Both medical and agricultural biotechnology can use genetic engineering, but the final products differ because the goals are:','["identical", "different", "unknown", "unimportant"]'::jsonb,1,'Goals differ by sector.','original'),
('127.475.d.7.A',3,'Molecules that store genetic information, such as DNA and RNA, are called:','["lipids", "minerals", "nucleic acids", "sugars"]'::jsonb,2,'DNA and RNA are nucleic acids.','original'),
('127.475.d.7.A',4,'The building blocks of nucleic acids, made of a sugar, a phosphate, and a base, are called:','["fatty acids", "enzymes", "amino acids", "nucleotides"]'::jsonb,3,'Nucleotides link to form DNA and RNA.','original'),
('127.475.d.7.B',3,'Compared with DNA, RNA usually has one strand and contains the base uracil instead of:','["thymine", "guanine", "cytosine", "adenine"]'::jsonb,0,'RNA uses U where DNA uses T.','original'),
('127.475.d.7.B',4,'DNA has a five-carbon sugar with one fewer oxygen atom than the five-carbon sugar found in RNA, which is:','["lactose", "ribose", "fructose", "glucose"]'::jsonb,1,'RNA has ribose.','original'),
('127.475.d.7.C',3,'Mitochondrial DNA in most animals is inherited from the:','["neighbor", "father only", "mother", "teacher"]'::jsonb,2,'The egg supplies the mitochondria.','original'),
('127.475.d.7.C',4,'Nuclear DNA in a child comes from both parents, but mitochondrial DNA comes from the egg, so it traces the line of the:','["uncle", "father", "grandfather only", "mother"]'::jsonb,3,'Maternal inheritance of mtDNA.','original'),
('127.475.d.7.D',3,'During DNA replication, the enzyme that joins new nucleotides to build the new strand is DNA:','["polymerase", "protease", "helicase only", "ligand"]'::jsonb,0,'Polymerase synthesizes DNA.','original'),
('127.475.d.7.D',4,'DNA replication is called semiconservative because each new double helix has one old strand and one:','["protein strand", "new strand", "old strand", "fat strand"]'::jsonb,1,'Each copy keeps half of the original.','original'),
('127.475.d.7.E',3,'Protein synthesis begins with copying a gene into messenger RNA in a process called:','["translation", "digestion", "transcription", "replication"]'::jsonb,2,'Transcription makes mRNA.','original'),
('127.475.d.7.E',4,'Ribosomes read the mRNA codons and assemble amino acids into a protein in the step called:','["transcription", "fermentation", "mutation", "translation"]'::jsonb,3,'Translation builds the protein.','original'),
('127.475.d.7.F',3,'The building blocks that join to make a protein are:','["amino acids", "simple sugars", "fatty acids", "nucleotides"]'::jsonb,0,'Proteins are chains of amino acids.','original'),
('127.475.d.7.F',4,'The three-dimensional shape of a protein determines its:','["address", "function", "name tag", "color only"]'::jsonb,1,'Shape determines function.','original'),
('127.475.d.7.G',3,'A promoter is a section of a gene where the enzyme that makes RNA attaches to start:','["digestion", "replication", "transcription", "respiration"]'::jsonb,2,'Promoters start transcription.','original'),
('127.475.d.7.G',4,'Enhancers are DNA sequences that can increase the rate of:','["protein digestion", "water loss", "cell death only", "gene expression"]'::jsonb,3,'Enhancers boost expression.','original'),
('127.475.d.7.H',3,'A mutation in which a segment of a chromosome is flipped end to end is an:','["inversion", "deletion", "translocation", "duplication"]'::jsonb,0,'Inversion reverses a segment.','original'),
('127.475.d.7.H',4,'A mutation where part of a chromosome is lost is a:','["substitution", "deletion", "insertion", "inversion"]'::jsonb,1,'Deletion removes DNA.','original'),
('127.475.d.7.I',3,'A mutation can change a protein and cause a different:','["planet", "genotype only", "phenotype", "season"]'::jsonb,2,'Altered proteins can change traits.','original'),
('127.475.d.7.I',4,'A mutation that changes a codon into a stop signal early in a gene usually makes the protein:','["edible", "identical", "longer and stronger", "shorter and often nonfunctional"]'::jsonb,3,'Premature stop truncates the protein.','original'),
('127.475.d.7.J',3,'The ends of a chromosome have protective caps called:','["telomeres", "centromeres", "ribosomes", "lysosomes"]'::jsonb,0,'Telomeres protect chromosome ends.','original'),
('127.475.d.7.J',4,'The region of a chromosome where sister chromatids attach is the:','["operon", "centromere", "telomere", "promoter"]'::jsonb,1,'Centromere joins chromatids.','original'),
('127.475.d.8.A',3,'The first step in recombinant DNA technology is to cut the gene of interest and the vector with the same:','["microscope slide", "pencil", "restriction enzyme", "thermometer"]'::jsonb,2,'Matching cuts allow joining.','original'),
('127.475.d.8.A',4,'After cutting, the gene and the vector are joined by the enzyme DNA:','["protease", "helicase", "polymerase", "ligase"]'::jsonb,3,'Ligase seals the joined pieces.','original'),
('127.475.d.8.B',3,'Making an animal that is genetically identical to another by placing a nucleus into an egg is called nuclear transfer:','["cloning", "tracking", "farming", "feeding"]'::jsonb,0,'Nuclear transfer creates clones.','original'),
('127.475.d.8.B',4,'Recombinant DNA technology lets scientists place a human gene into bacteria to make a useful:','["fuel only", "protein", "fabric", "rock"]'::jsonb,1,'Bacteria can produce human proteins.','original'),
('127.475.d.8.C',3,'Growing plant or animal cells in a lab dish on nutrient medium is called tissue:','["painting", "rotation", "culture", "drainage"]'::jsonb,2,'Tissue culture grows cells in vitro.','original'),
('127.475.d.8.C',4,'Tissue culture helps genetic modification because modified cells can be grown into whole:','["rocks", "metals", "clouds", "plants or tissues"]'::jsonb,3,'Cells can regenerate.','original'),
('127.475.d.8.D',3,'Plant tissue culture is usually done on a gel-like medium kept free of germs by:','["sterile technique", "sunlight only", "dirty tools", "open air"]'::jsonb,0,'Sterility prevents contamination.','original'),
('127.475.d.8.D',4,'Animal cell cultures are grown in liquid medium that often contains serum, which supplies:','["bleach", "growth factors", "salt only", "gasoline"]'::jsonb,1,'Serum provides nutrients and growth factors.','original'),
('127.475.d.8.E',3,'Plant tissue cultures need light and plant hormones, while mammalian cell cultures are kept at about:','["0 degrees Celsius", "-20 degrees Celsius", "37 degrees Celsius", "100 degrees Celsius"]'::jsonb,2,'Body temperature supports mammalian cells.','original'),
('127.475.d.8.E',4,'Animal cell cultures are usually grown in an incubator with carbon dioxide to control the medium''s:','["color", "sound", "smell", "pH"]'::jsonb,3,'CO2 helps buffer pH.','original'),
('127.475.d.8.F',3,'Restriction enzymes act like molecular scissors because they cut DNA at specific:','["sequences", "pages", "times", "colors"]'::jsonb,0,'They recognize base sequences.','original'),
('127.475.d.8.F',4,'The sequence a restriction enzyme recognizes is called its:','["promoter", "recognition site", "gene pool", "telomere"]'::jsonb,1,'Each enzyme has a site.','original'),
('127.475.d.8.G',3,'A circular piece of bacterial DNA often used to carry a gene into a cell is a:','["lysosome", "ribosome", "plasmid", "chloroplast"]'::jsonb,2,'Plasmids are common vectors.','original'),
('127.475.d.8.G',4,'Besides plasmids, a virus that has been modified to carry genes into cells is used as a:','["growth chart", "filter paper", "food label", "viral vector"]'::jsonb,3,'Viruses can be vectors.','original'),
('127.475.d.9.A',3,'In the United States, the agency that approves new drugs and vaccines is the:','["Food and Drug Administration", "Postal Service", "Park Service", "Weather Service"]'::jsonb,0,'The FDA regulates drugs.','original'),
('127.475.d.9.A',4,'Local, state, and federal agencies all play roles in biotechnology by setting rules for safety, testing, and:','["sports", "approval of products", "fashion", "music"]'::jsonb,1,'Agencies regulate products.','original'),
('127.475.d.9.B',3,'Biotechnology companies follow written procedures so that products are made the same way every time. These written steps are called:','["jokes", "menus", "standard operating procedures", "suggestions"]'::jsonb,2,'SOPs ensure consistency.','original'),
('127.475.d.9.B',4,'Policies such as Good Laboratory Practice help ensure that studies are:','["secret", "very fast only", "cheap only", "accurate and reliable"]'::jsonb,3,'GLP supports data integrity.','original'),
('127.475.d.10.A',3,'A technician who needs to weigh 2.5 grams of reagent should use a:','["balance", "compass", "clock", "ruler"]'::jsonb,0,'A balance measures mass.','original'),
('127.475.d.10.A',4,'For accuracy, a balance should be zeroed and the reagent should be placed in a weigh boat so the technician can measure the:','["day of the week", "correct mass", "color of the room", "noise level"]'::jsonb,1,'Tare the container first.','original'),
('127.475.d.10.B',3,'A technician measures a sample three times and gets 4.1, 4.3, and 4.2. The mean is:','["12.6", "4.3", "4.2", "4.1"]'::jsonb,2,'(4.1 + 4.3 + 4.2)/3 = 4.2.','original'),
('127.475.d.10.B',4,'Standard deviation tells how much repeated measurements are:','["expensive", "colored", "heavy", "spread out"]'::jsonb,3,'Standard deviation measures spread.','original'),
('127.475.d.10.C',3,'When pipetting, the technician should hold the pipette vertically and draw up liquid slowly to avoid:','["bubbles", "notebooks", "gloves", "labels"]'::jsonb,0,'Bubbles cause volume errors.','original'),
('127.475.d.10.C',4,'A micropipette is set to 50 microliters. Moving the dial to a different number would change the volume:','["of the room", "dispensed", "of the lab", "of the day"]'::jsonb,1,'The dial sets the volume.','original'),
('127.475.d.10.D',3,'The Gram stain divides bacteria into two groups, Gram-positive and:','["Gram-neutral", "Gram-free", "Gram-negative", "Gram-silent"]'::jsonb,2,'Gram status depends on the cell wall.','original'),
('127.475.d.10.D',4,'Gram-positive bacteria appear purple because their thick cell walls hold onto:','["water", "iodine only", "alcohol only", "crystal violet"]'::jsonb,3,'Thick peptidoglycan keeps the violet dye.','original'),
('127.475.d.10.E',3,'A restriction digest cuts DNA, and the pieces can be separated and viewed using:','["gel electrophoresis", "magnets only", "sound waves", "thin layer paint"]'::jsonb,0,'Gel electrophoresis separates by size.','original'),
('127.475.d.10.E',4,'On a gel, smaller DNA fragments move:','["not at all", "farther", "to the wells", "backward"]'::jsonb,1,'Small pieces travel faster through the gel.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_70_v1'
from (values
('127.475.d.10.F',3,'Nutrient broth and agar supply what bacteria need to grow. These materials are called culture:','["badges", "walls", "media", "screens"]'::jsonb,2,'Media feed cultures.','original'),
('127.475.d.10.F',4,'If the wrong nutrients are in a medium, the culture may grow slowly or not at all, showing why media components affect the:','["building", "date", "weather", "outcome"]'::jsonb,3,'Media affect growth.','original'),
('127.475.d.10.G',3,'Microbial cultures are stored safely in labeled containers, often at cold temperatures, to keep them:','["viable and uncontaminated", "noisy", "warm", "colorful"]'::jsonb,0,'Storage preserves cultures.','original'),
('127.475.d.10.G',4,'A freezer stock of bacteria is often made by mixing the culture with glycerol, which protects cells from:','["learning", "freezing damage", "reporting", "reading"]'::jsonb,1,'Glycerol is a cryoprotectant.','original'),
('127.475.d.10.H',3,'A small starter culture used to begin a larger culture is called a seed:','["journal", "catalog", "inoculum", "receipt"]'::jsonb,2,'Seed inoculum starts a larger batch.','original'),
('127.475.d.10.H',4,'A seed culture is grown to a healthy stage before being added to a larger tank so the large culture can start growing:','["noisily", "backward", "in secret", "quickly"]'::jsonb,3,'A healthy start speeds growth.','original'),
('127.475.d.10.I',3,'Spreading a small amount of liquid culture over an agar plate with a sterile spreader is called:','["spread plating", "pipe laying", "streak flying", "pour boiling"]'::jsonb,0,'Spread plating isolates colonies.','original'),
('127.475.d.10.I',4,'Using a loop to drag bacteria across an agar surface in a pattern to get single colonies is:','["dry plating", "streak plating", "pour painting", "spread plating"]'::jsonb,1,'Streaking dilutes cells across the plate.','original'),
('127.475.d.11.A',3,'Aseptic technique helps keep a culture from becoming:','["brighter", "warmer", "contaminated", "heavier"]'::jsonb,2,'Aseptic work excludes unwanted microbes.','original'),
('127.475.d.11.A',4,'Flaming a loop before and after use is an example of aseptic technique because it:','["adds nutrients", "cools the room", "dries the agar", "kills microbes on the loop"]'::jsonb,3,'Heat sterilizes the loop.','original'),
('127.475.d.11.B',3,'A stock reagent is usually stored in a labeled bottle that shows its name, concentration, and:','["date prepared", "price of lunch", "weather", "owner''s favorite color"]'::jsonb,0,'Labels track identity and age.','original'),
('127.475.d.11.B',4,'A technician checks the pH of a buffer with a pH meter because the physical properties of a reagent must be:','["hidden", "monitored", "guessed", "ignored"]'::jsonb,1,'pH is a physical property to monitor.','original'),
('127.475.d.11.C',3,'A dilution series in which each tube is 1 to 10 of the one before is called a:','["double mixture", "random mix", "tenfold serial dilution", "fraction chart"]'::jsonb,2,'Each step dilutes 10 times.','original'),
('127.475.d.11.C',4,'If 1 mL of sample is added to 9 mL of diluent, the dilution factor is:','["9", "1", "90", "10"]'::jsonb,3,'Total volume 10 mL divided by 1 mL.','original'),
('127.475.d.11.D',3,'Before running an experiment, a scientist finds the best temperature and pH for an enzyme by testing a range of:','["conditions", "rumors", "colors", "names"]'::jsonb,0,'Optimization tests conditions.','original'),
('127.475.d.11.D',4,'The optimum pH for an enzyme is the pH at which the enzyme shows its:','["lowest activity", "highest activity", "slowest decay", "weakest bonds"]'::jsonb,1,'Optimum is the peak of activity.','original'),
('127.475.d.12.A',3,'Checking that a balance gives correct readings by using a known standard weight is part of:','["hiring", "shipping", "validation testing", "advertising"]'::jsonb,2,'Validation confirms performance.','original'),
('127.475.d.12.A',4,'A lab validates a new reagent lot by confirming that it works as well as the:','["packaging", "invoice", "delivery truck", "previous lot"]'::jsonb,3,'Validation compares performance.','original'),
('127.475.d.12.B',3,'A scientist who finds the mean and standard deviation of her results is performing:','["statistical analysis", "note taking only", "map reading", "bottle labeling"]'::jsonb,0,'Statistics summarize data.','original'),
('127.475.d.12.B',4,'A result is reliable when repeated trials give values that are:','["missing", "close together", "far apart", "identical to an unrelated test"]'::jsonb,1,'Reproducibility indicates reliability.','original'),
('127.476.d.1.A',3,'A researcher notices that a gene seems to turn on only in heat. Turning this observation into a testable question is the first step of:','["shipping", "marketing", "scientific inquiry", "accounting"]'::jsonb,2,'Inquiry begins with questions.','original'),
('127.476.d.1.A',4,'A well-defined problem in a biotechnology lab names what is being studied and what will be:','["decorated", "hidden", "ignored", "measured"]'::jsonb,3,'Problems must be measurable.','original'),
('127.476.d.1.B',3,'A plan for an experiment lists the variable to change, the variable to measure, and the factors to keep:','["constant", "random", "secret", "hidden"]'::jsonb,0,'Controls keep conditions constant.','original'),
('127.476.d.1.B',4,'Running three identical plates for each condition is done so that results are not due to:','["planning", "chance", "design", "labeling"]'::jsonb,1,'Replication reduces chance error.','original'),
('127.476.d.1.C',3,'A biosafety cabinet is used when working with cultures to protect both the worker and the:','["radio", "floor", "sample", "window"]'::jsonb,2,'Cabinets protect people and samples.','original'),
('127.476.d.1.C',4,'Before leaving a lab where cultures were used, a worker should wash hands and disinfect the:','["ceiling", "windows", "floor tiles", "work surface"]'::jsonb,3,'Disinfection prevents spread.','original'),
('127.476.d.1.D',3,'A device that measures how acidic or basic a solution is, is a:','["pH meter", "scale model", "clock", "ruler"]'::jsonb,0,'pH meters read acidity.','original'),
('127.476.d.1.D',4,'A spectrophotometer measures how much light a solution absorbs, which can reveal its:','["cost", "concentration", "address", "owner"]'::jsonb,1,'Absorbance relates to concentration.','original'),
('127.476.d.1.E',3,'In SI units, the base unit of length is the:','["yard", "mile", "meter", "foot"]'::jsonb,2,'The meter is the SI unit of length.','original'),
('127.476.d.1.E',4,'A volume recorded as 2,500 microliters equals how many milliliters?','["0.25", "250", "25", "2.5"]'::jsonb,3,'1,000 microliters equal 1 mL.','original'),
('127.476.d.1.F',3,'Recording results right away in a lab notebook helps prevent:','["lost or incorrect information", "extra sleep", "new tools", "free time"]'::jsonb,0,'Prompt records are accurate.','original'),
('127.476.d.1.F',4,'Digital notebooks and spreadsheets can organize quantitative data and make it easy to create:','["weather", "graphs", "menus", "jokes"]'::jsonb,1,'Software helps analysis.','original'),
('127.476.d.1.G',3,'A computer simulation of how a drug moves through the body is a:','["label", "receipt", "model", "badge"]'::jsonb,2,'Simulations are models.','original'),
('127.476.d.1.G',4,'Flowcharts, diagrams, and equations can all represent a biological:','["holiday", "contest", "fashion", "process"]'::jsonb,3,'Models show processes.','original'),
('127.476.d.1.H',3,'A testable prediction about what will happen in an experiment is a:','["hypothesis", "law", "conclusion", "theory"]'::jsonb,0,'Hypotheses are testable.','original'),
('127.476.d.1.H',4,'A hypothesis becomes part of a theory only after it has been supported by:','["a rumor", "many experiments", "a single guess", "a poll"]'::jsonb,1,'Theories rely on repeated support.','original'),
('127.476.d.2.A',3,'A limitation of a mouse model for human disease is that mice are not exactly like:','["plants", "mice", "humans", "bacteria"]'::jsonb,2,'Models differ from the real system.','original'),
('127.476.d.2.A',4,'A cell culture model is smaller and simpler than a whole body, so it cannot show how:','["ink flows", "pencils write", "a dish is shaped", "organs interact"]'::jsonb,3,'Culture models lack whole-body complexity.','original'),
('127.476.d.2.B',3,'A line of best fit on a scatterplot helps a scientist see the:','["trend", "title", "author", "border"]'::jsonb,0,'Trendlines show patterns.','original'),
('127.476.d.2.B',4,'If one reading is far from all the others in a data set, a scientist should investigate whether it is an:','["constant", "outlier", "average", "median"]'::jsonb,1,'Outliers need review.','original'),
('127.476.d.2.C',3,'If a solution has 10 grams of solute in 2 liters, the concentration in grams per liter is:','["20", "12", "5", "0.2"]'::jsonb,2,'10 / 2 = 5.','original'),
('127.476.d.2.C',4,'A bacterial culture doubles every 30 minutes. Starting with 100 cells, after 2 hours there will be:','["400", "800", "200", "1,600"]'::jsonb,3,'4 doublings: 100 x 16.','original'),
('127.476.d.2.D',3,'Testing whether a bioreactor design meets goals for yield and safety is called:','["evaluating the design", "selling", "naming", "decorating"]'::jsonb,0,'Evaluation uses criteria.','original'),
('127.476.d.2.D',4,'Engineers improve experimental designs by comparing results with the original goals and then making:','["excuses", "changes", "lunches", "posters"]'::jsonb,1,'Iteration improves design.','original'),
('127.476.d.3.A',3,'A claim that a protein is made in cells at higher levels is strongest when supported by a:','["feeling", "opinion", "data table and graph", "title"]'::jsonb,2,'Evidence supports explanations.','original'),
('127.476.d.3.A',4,'A proposed solution should be backed by data and a:','["coin flip", "rumor", "slogan", "model"]'::jsonb,3,'Models plus data support solutions.','original'),
('127.476.d.3.B',3,'Scientists communicate their findings to the public in clear language and with:','["visuals", "puzzles", "silence", "codes"]'::jsonb,0,'Visuals help communication.','original'),
('127.476.d.3.B',4,'Collaboration on a lab team works best when everyone has a clear role and shares results openly to improve the final:','["delay", "solution", "dispute", "debt"]'::jsonb,1,'Teamwork improves outcomes.','original'),
('127.476.d.3.C',3,'A scientist who is respectful in an argument focuses on the:','["person", "clothing", "evidence", "accent"]'::jsonb,2,'Debate evidence, not people.','original'),
('127.476.d.3.C',4,'When two scientists reach different conclusions from the same data, they should:','["stop working", "trade insults", "hide data", "explain their reasoning and test further"]'::jsonb,3,'Further testing resolves disputes.','original'),
('127.476.d.4.A',3,'Evaluating a scientific explanation involves checking whether the conclusions follow from the:','["data", "length", "headline", "price"]'::jsonb,0,'Conclusions must follow from evidence.','original'),
('127.476.d.4.A',4,'A critic of a study notices that the sample size was only 3 people. The critic would say the study lacks:','["a sponsor", "statistical power", "a title", "a deadline"]'::jsonb,1,'Small samples limit conclusions.','original'),
('127.476.d.4.B',3,'The development of PCR in the 1980s changed science by making it possible to copy tiny amounts of:','["sand", "water", "DNA", "metal"]'::jsonb,2,'PCR amplifies DNA.','original'),
('127.476.d.4.B',4,'Research on the human genome has changed medicine by helping doctors tailor treatments to a patient''s:','["address", "clothes", "school", "genes"]'::jsonb,3,'Genomics enables personalized medicine.','original'),
('127.476.d.4.C',3,'A student exploring careers in biotechnology could interview a:','["laboratory scientist", "video game", "random stranger", "tourist"]'::jsonb,0,'Professionals give career insight.','original')
