('127.476.d.9.F',4,'CRISPR is being studied as a way to correct disease-causing mutations and also as a tool for rapid diagnostic:','["stories", "recipes", "costumes", "tests"]'::jsonb,3,'CRISPR can detect nucleic acids.','original'),
('127.476.d.10.A',3,'A sterile workspace for culture work is prepared by wiping surfaces with disinfectant and working near a flame or inside a:','["laminar flow hood", "garage", "closet", "window"]'::jsonb,0,'A hood provides a sterile field.','original'),
